BEGIN READ ONLY; SET LOCAL statement_timeout='20s';
WITH outside_relations AS (SELECT n.nspname,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) AS owner,c.relacl::text AS acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','auth') AND NOT(n.nspname='public' AND c.relname=ANY(ARRAY['edu_comm_acknowledgements','edu_comm_consent_responses','edu_comm_deliveries','edu_comm_delivery_attempts','edu_comm_exceptions','edu_comm_notices','edu_comm_responses','edu_comm_sent_snapshots','edu_comm_threads','edu_fac_assets','edu_fac_facilities','edu_fac_inspection_logs','edu_fac_inspection_schedules','edu_fac_maintenance_jobs','edu_fac_out_of_service_logs','edu_fac_zones','edu_fin_billing_periods','edu_fin_fee_structures','edu_fin_invoice_line_items','edu_fin_invoices','edu_fin_payments','edu_fin_receipts','edu_fin_reconciliation_ledger','edu_fin_student_discount_profiles','edu_sched_compliance_snapshots','edu_sched_leave_requests','edu_sched_ratio_policies','edu_sched_shift_assignments','edu_sched_shift_templates','edu_sched_staff_availability','edu_sched_substitutions','students']))), all_policies AS(SELECT * FROM pg_policies WHERE schemaname IN ('public','auth')), other_functions AS(SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) AS args,p.prosecdef,pg_get_userbyid(p.proowner) AS owner,p.proacl::text AS acl,p.proconfig,md5(pg_get_functiondef(p.oid)) AS definition_hash FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','auth') AND p.prokind='f' AND p.oid<>to_regprocedure('public.exec_sql(text)')) SELECT jsonb_build_object('outside_relations_count',(SELECT count(*) FROM outside_relations),'outside_relation_hash',(SELECT md5(jsonb_agg(to_jsonb(r) ORDER BY nspname,relname)::text) FROM outside_relations r),'all_policy_hash',(SELECT md5(jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname)::text) FROM all_policies p),'other_function_hash',(SELECT md5(jsonb_agg(to_jsonb(f) ORDER BY nspname,proname,args)::text) FROM other_functions f),'full_membership_hash',(SELECT md5(jsonb_agg(to_jsonb(m) ORDER BY roleid,member,grantor)::text) FROM pg_auth_members m),'full_role_hash',(SELECT md5(jsonb_agg((to_jsonb(r)-'rolvaliduntil') ORDER BY rolname)::text) FROM pg_roles r),'schema_acl_hash',(SELECT md5(jsonb_agg(jsonb_build_object('schema',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) ORDER BY nspname)::text) FROM pg_namespace WHERE nspname NOT LIKE 'pg_temp_%' AND nspname NOT LIKE 'pg_toast_temp_%'),'default_acl_hash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(a) ORDER BY oid)::text,'[]')) FROM pg_default_acl a)) AS evidence;
ROLLBACK;
